<script setup>
import {Head,Link,router,usePage} from '@inertiajs/vue3'
import AppLayout from '../../Layouts/AppLayout.vue'
const p=defineProps({course:Object,students:Object,summary:Object,filters:Object,enrollmentStatuses:Array})
const role=usePage().props.auth.user.role.toLowerCase()
const stateLabel=s=>({not_started:'شروع‌نشده',in_progress:'در حال پیشرفت',completed:'تکمیل‌شده'}[s]||s)
const search=()=>router.get(`/${role}/reports/courses/${p.course.id}`,p.filters,{preserveState:true,replace:true})
const exportUrl=()=>`/${role}/reports/courses/${p.course.id}/export?${new URLSearchParams(Object.entries(p.filters).filter(([,v])=>v!==''&&v!=null))}`
</script>
<template><AppLayout><Head :title="`گزارش ${course.title}`"/><div class="space-y-5"><section class="rounded-2xl border bg-white p-5"><Link :href="`/${role}/reports`" class="text-teal-700">بازگشت به گزارش‌ها</Link><div class="mt-3 flex flex-wrap justify-between gap-3"><h1 class="text-2xl font-bold">{{course.title}}</h1><a :href="exportUrl()" class="rounded-xl border border-teal-700 px-4 py-2 text-teal-800">خروجی CSV</a></div><div class="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><div class="rounded-xl bg-slate-50 p-3">ثبت‌نام فعال<br><strong>{{summary.active_enrollments}}</strong></div><div class="rounded-xl bg-slate-50 p-3">درس در دسترس<br><strong>{{summary.available_lessons}}</strong></div><div class="rounded-xl bg-slate-50 p-3">میانگین پیشرفت<br><strong>{{summary.average_progress}}٪</strong></div><div class="rounded-xl bg-slate-50 p-3">تکمیل‌شده<br><strong>{{summary.completed}}</strong></div></div></section>
<section class="rounded-2xl border bg-white p-5"><form class="grid gap-3 md:grid-cols-3" @submit.prevent="search"><input v-model="filters.student" placeholder="جستجوی نام یا موبایل"><select v-model="filters.enrollment_status"><option value="">همه ثبت‌نام‌ها</option><option v-for="s in enrollmentStatuses" :value="s">{{s}}</option></select><select v-model="filters.progress_state"><option value="">همه وضعیت‌های پیشرفت</option><option value="not_started">شروع‌نشده</option><option value="in_progress">در حال پیشرفت</option><option value="completed">تکمیل‌شده</option></select><input v-model="filters.min_progress" type="number" min="0" max="100" placeholder="حداقل درصد"><input v-model="filters.max_progress" type="number" min="0" max="100" placeholder="حداکثر درصد"><select v-model="filters.inactive_days"><option value="">همه فعالیت‌ها</option><option value="7">بدون فعالیت ۷ روز</option><option value="14">بدون فعالیت ۱۴ روز</option><option value="30">بدون فعالیت ۳۰ روز</option></select><button class="rounded-xl bg-teal-700 px-4 py-2 text-white">اعمال فیلتر</button></form></section>
<section class="rounded-2xl border bg-white p-3 sm:p-5"><div class="overflow-x-auto"><table class="w-full min-w-[900px] text-sm"><thead><tr class="border-b text-right"><th class="p-3">هنرجو</th><th>پیشرفت</th><th>درس‌ها</th><th>تکالیف</th><th>پرسش‌ها</th><th>آخرین فعالیت</th><th></th></tr></thead><tbody><tr v-for="row in students.data" :key="row.id" class="border-b"><td class="p-3">{{row.student.first_name}} {{row.student.last_name}}<small class="block text-slate-500">{{row.student.mobile}}</small></td><td><strong>{{row.progress.percent}}٪</strong><div class="mt-1 h-2 w-28 rounded bg-slate-200"><div class="h-2 rounded bg-teal-600" :style="{width:row.progress.percent+'%'}"></div></div><small>{{stateLabel(row.progress_state)}}</small></td><td>{{row.progress.completed_lessons}} / {{row.progress.total_lessons}}</td><td>{{row.assignments.submitted}} ارسال، {{row.assignments.not_submitted}} باقی‌مانده<Link v-if="row.assignments.latest_submission_id" :href="`/submissions/${row.assignments.latest_submission_id}`" class="block text-teal-700">مشاهده آخرین ارسال</Link></td><td>{{row.questions.open}} باز / {{row.questions.total}} کل</td><td>{{row.last_activity_at?new Date(row.last_activity_at).toLocaleString('fa-IR'):'بدون فعالیت'}}</td><td><Link :href="`/${role}/reports/students/${row.student.id}?course=${course.id}`" class="text-teal-700">جزئیات</Link></td></tr></tbody></table></div><p v-if="!students.data.length" class="p-5 text-center text-slate-500">نتیجه‌ای مطابق فیلترها یافت نشد.</p><div class="mt-4 flex flex-wrap gap-2"><Link v-for="link in students.links" :key="link.label" :href="link.url||'#'" v-html="link.label" class="rounded border px-3 py-1" :class="{'bg-teal-700 text-white':link.active}"/></div></section></div></AppLayout></template>
